/**
 * ranges.mjs — compact sorted-range sets over Unicode code points.
 *
 * A range set is a flat Int32Array-like array of ascending pairs:
 *   [lo0, hi0, lo1, hi1, ...]   (inclusive bounds, non-overlapping, ascending)
 * Lookup is O(log n) binary search, which keeps the large IDNA/UTS46 tables cheap.
 */

/** Build a flat range set from an array of [lo, hi] pairs (or bare ints). */
export function makeRangeSet(pairs) {
  const norm = [];
  for (const p of pairs) {
    const lo = Array.isArray(p) ? p[0] : p;
    const hi = Array.isArray(p) ? (p.length > 1 ? p[1] : p[0]) : p;
    norm.push([lo, hi]);
  }
  norm.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (const [lo, hi] of norm) {
    const last = merged.length ? merged[merged.length - 1] : null;
    if (last && lo <= last[1] + 1) {
      if (hi > last[1]) last[1] = hi;
    } else {
      merged.push([lo, hi]);
    }
  }
  const flat = new Int32Array(merged.length * 2);
  for (let i = 0; i < merged.length; i++) {
    flat[i * 2] = merged[i][0];
    flat[i * 2 + 1] = merged[i][1];
  }
  return flat;
}

/**
 * Decode the compact string encoding used by the generated tables.
 * Format: base-36 deltas, ";"-separated entries of "<startDelta>[+<span>]".
 * startDelta is measured from the end of the previous range.
 */
export function decodeRangeSet(encoded) {
  if (!encoded) return new Int32Array(0);
  const parts = encoded.split(';');
  const flat = new Int32Array(parts.length * 2);
  let prev = -1;
  for (let i = 0; i < parts.length; i++) {
    const plus = parts[i].indexOf('+');
    const d = parseInt(plus < 0 ? parts[i] : parts[i].slice(0, plus), 36);
    const span = plus < 0 ? 0 : parseInt(parts[i].slice(plus + 1), 36);
    const lo = prev + 1 + d;
    const hi = lo + span;
    flat[i * 2] = lo;
    flat[i * 2 + 1] = hi;
    prev = hi;
  }
  return flat;
}

/** Encode a flat range set back to the compact string form (used by tools/gen). */
export function encodeRangeSet(flat) {
  const out = [];
  let prev = -1;
  for (let i = 0; i < flat.length; i += 2) {
    const lo = flat[i], hi = flat[i + 1];
    const d = lo - prev - 1;
    out.push(hi > lo ? `${d.toString(36)}+${(hi - lo).toString(36)}` : d.toString(36));
    prev = hi;
  }
  return out.join(';');
}

/** True when cp falls inside the range set. */
export function inRangeSet(flat, cp) {
  let lo = 0, hi = (flat.length >> 1) - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < flat[mid * 2]) hi = mid - 1;
    else if (cp > flat[mid * 2 + 1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/** Total number of code points covered. */
export function rangeSetSize(flat) {
  let n = 0;
  for (let i = 0; i < flat.length; i += 2) n += flat[i + 1] - flat[i] + 1;
  return n;
}

/** Iterate every code point in the set. */
export function* rangeSetPoints(flat) {
  for (let i = 0; i < flat.length; i += 2) {
    for (let cp = flat[i]; cp <= flat[i + 1]; cp++) yield cp;
  }
}

