/**
 * pyformat.mjs — CPython-compatible str/bytes repr and print().
 *
 * The Python program prints `bytes` objects (idna.encode / idna.alabel results) and interpolates
 * `repr()`ed labels into IDNAError messages, so both reprs have to be byte-exact.
 */

/** Code points that `str.isprintable()` reports False for: categories Cc Cf Cs Co Cn Zl Zp Zs.
 *  ASCII space (U+0020) is the one Zs code point Python still calls printable. */
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** Node's Unicode is 15.1 while the reference CPython is 15.0; treat the 15.1-only additions as
 *  unassigned (Cn) so `isprintable()` agrees with the reference. They are Han + IDC, i.e. printable
 *  in 15.1 but unassigned in 15.0 — see unicodedata15.mjs for the shared delta definition. */
import { isUnassignedIn15_0 } from './unicode/unicodedata15.mjs';

export function isPrintable(cp) {
  if (cp === 0x20) return true;
  if (isUnassignedIn15_0(cp)) return false;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

function hexEsc(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * repr() of a Python str. `cps` may be a string or an array of code points.
 * Quote choice mirrors CPython: single quotes, unless the value contains a "'" and no '"'.
 */
export function pyRepr(value) {
  const cps = typeof value === 'string' ? Array.from(value, c => c.codePointAt(0)) : value;
  const hasSingle = cps.includes(0x27);
  const hasDouble = cps.includes(0x22);
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  let out = String.fromCodePoint(quote);
  for (const cp of cps) {
    if (cp === quote || cp === 0x5c) out += '\\' + String.fromCodePoint(cp);
    else if (cp === 0x09) out += '\\t';
    else if (cp === 0x0a) out += '\\n';
    else if (cp === 0x0d) out += '\\r';
    else if (isPrintable(cp)) out += String.fromCodePoint(cp);
    else out += hexEsc(cp);
  }
  return out + String.fromCodePoint(quote);
}

/** repr() of a Python bytes object. `bytes` is an array of 0..255 values. */
export function pyReprBytes(bytes) {
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  let out = "b" + String.fromCharCode(quote);
  for (const b of bytes) {
    if (b === quote || b === 0x5c) out += '\\' + String.fromCharCode(b);
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b >= 0x20 && b < 0x7f) out += String.fromCharCode(b);
    else out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + String.fromCharCode(quote);
}

/** U+XXXX form used by idna's `_unot()` — always at least 4 upper-case hex digits. */
export function unot(cp) {
  return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
}

