/**
 * unicodedata15.mjs — emulation of the reference CPython 3.12 `unicodedata` module (Unicode 15.0).
 *
 * Node 18 ships Unicode 15.1 property data. Unicode 15.1 added exactly 627 code points over 15.0:
 *   U+2EBF0..U+2EE5D  CJK Unified Ideographs Extension I (622)
 *   U+2FFC..U+2FFF    ideographic description characters (4)
 *   U+31EF            IDEOGRAPHIC DESCRIPTION CHARACTER SUBTRACTION (1)
 * and changed no existing property values. Reporting those as unassigned is therefore enough to make
 * `category()` / `bidirectional()` agree with the reference build — which matters, because idna's own
 * tables are Unicode 16.0 and accept code points `unicodedata` has never heard of, producing
 * "Unknown directionality in label ... at position N".
 */

export function isUnassignedIn15_0(cp) {
  return (cp >= 0x2ebf0 && cp <= 0x2ee5d) || (cp >= 0x2ffc && cp <= 0x2fff) || cp === 0x31ef;
}

const RE_M = /^\p{M}$/u;

/** unicodedata.category(ch)[0] === 'M' — used by idna's check_initial_combiner. */
export function isCombiningCategory(cp) {
  if (isUnassignedIn15_0(cp)) return false;
  return RE_M.test(String.fromCodePoint(cp));
}

/** unicodedata.normalize('NFC', s). Unicode 15.1 introduced no new decompositions, so Node's
 *  normalize() is identical to the reference build's for every code point. */
export function nfc(s) {
  return s.normalize('NFC');
}

