/**
 * codec.mjs — RFC 3492 Punycode, implemented to match CPython's `encodings/punycode.py` exactly
 * (including its quirks: `.upper()` on the extended part, `rfind('-')` delimiter search, no
 * surrogate rejection, and no delimiter when the basic string is empty).
 *
 * Strings are handled as code point arrays throughout, because Python strings are sequences of
 * code points while JS strings are UTF-16 sequences.
 */

const DIGITS = 'abcdefghijklmnopqrstuvwxyz0123456789';

/** Error thrown where CPython's codec raises UnicodeError / UnicodeDecodeError. */
export class PunycodeError extends Error {
  constructor(message, kind) {
    super(message);
    this.name = 'UnicodeError';
    this.kind = kind; // 'invalid-digit' | 'incomplete' | 'invalid-character'
  }
}

function T(j, bias) {
  const res = 36 * (j + 1) - bias;
  if (res < 1) return 1;
  if (res > 26) return 26;
  return res;
}

