/**
 * ccc.mjs — canonical combining class facts that Node exposes no property escape for.
 *
 * idna only needs one question answered: "is this code point a virama?", i.e. ccc == 9.
 * That is recoverable from Node's own normalizer: canonical ordering swaps two adjacent
 * non-starters exactly when the first has a strictly greater combining class. Comparing a
 * candidate against a known ccc==9 mark (U+094D DEVANAGARI SIGN VIRAMA) in both orders pins
 * equality without needing any embedded table.
 */

const BASE = '一'; // a starter that takes part in no canonical composition
const VIRAMA = '्'; // ccc = 9
const ABOVE = '́'; // ccc = 230, used to prove ccc > 0

const cache = new Map();

function stable(a, b) {
  const s = BASE + a + b;
  return s.normalize('NFD') === s;
}

/** True when unicodedata.combining(chr(cp)) === 9. */
export function isVirama(cp) {
  const hit = cache.get(cp);
  if (hit !== undefined) return hit;
  let res = false;
  const ch = String.fromCodePoint(cp);
  // A decomposable or composing char is never a bare virama; skip it so NFD cannot confuse us.
  if (ch.normalize('NFD') === ch) {
    // ccc > 0 (U+0301 has ccc 230, so anything with 0 < ccc < 230 reorders in front of it)
    const nonStarter = !stable(ABOVE, ch);
    res = nonStarter && stable(ch, VIRAMA) && stable(VIRAMA, ch);
  }
  cache.set(cp, res);
  return res;
}

/** True when unicodedata.combining(chr(cp)) !== 0. */
export function hasCombiningClass(cp) {
  const ch = String.fromCodePoint(cp);
  if (ch.normalize('NFD') !== ch) return false;
  return !stable(ABOVE, ch) || !stable(ch, ABOVE);
}

